pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a minimal ERC721 to use as nft
        // We'll use a simple inline contract for the test
        vm.etch(address(0x2222), abi.encodePacked(
            type(MinimalNFT).runtimeCode
        ));

        address baseToken = address(0x1111);
        address nft = address(0x2222);
        uint128 virtualBase = 1000 ether;
        uint128 virtualNft = 100;
        uint56 changeFee = 0;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolen = false;
        bool payRoyalties = false;

        // Prank as the factory owner to initialize
        vm.prank(address(this));
        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties);

        // Now call availableForFlashLoan with the nft address and tokenId 1
        // Reference: nft = 0x2222, so nft.ownerOf(1) will be checked
        // Bug: baseToken = 0x2222, so baseToken.ownerOf(1) will be checked (which doesn't exist)
        bool result;
        try c.availableForFlashLoan(nft, 1) returns (bool res) {
            result = res;
        } catch {
            result = false;
        }

        // Reference should return false because nft is not owned by this contract
        // Bug should return true because it's checking the wrong address (0x1111 which has no code)
        assertTrue(result == false, "Bug should have returned false but got true");
    }
}

contract MinimalNFT {
    function ownerOf(uint256) external pure returns (address) {
        return address(0);
    }
}

