contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a simple ERC721 token to use as the NFT
        // We can use a dummy contract that mints a token to this test contract
        // Instead, we'll initialize the pool with baseToken=address(this) and nft=address(0xdead)
        // Then we'll check availableForFlashLoan with the nft address

        // Use address(0xdead) as nft (external account, no code)
        address nft = address(0xdead);

        // Initialize the pool with baseToken=address(this), nft=address(0xdead)
        c.initialize(
            address(this),   // _baseToken
            nft,              // _nft
            1000,             // _virtualBaseTokenReserves
            1000,             // _virtualNftReserves
            0,                // _changeFee
            100,              // _feeRate (1%)
            0x0,              // _merkleRoot
            false,            // _useStolenNftOracle
            false             // _payRoyalties
        );

        // On the reference: baseToken = address(this), nft = address(0xdead)
        // availableForFlashLoan(nft, 1) calls ERC721(address(0xdead)).ownerOf(1)
        // Since address(0xdead) has no code, ownerOf reverts, so availableForFlashLoan returns false

        // On the buggy version: baseToken = address(0xdead) (wrongly assigned from _nft)
        // nft = address(this) (wrongly assigned from _baseToken)
        // availableForFlashLoan(nft, 1) calls ERC721(address(this)).ownerOf(1)
        // address(this) is the test contract; ERC721.ownerOf(1) will revert because _ownerOf[1] is 0
        // So availableForFlashLoan returns false on both? 
        // Let's rethink: the bug swaps baseToken and nft.
        // So for the reference: baseToken = address(this), nft = 0xdead
        // for the bug: baseToken = 0xdead, nft = address(this)
        // Calling availableForFlashLoan(nft, 1) with nft = 0xdead:
        // Reference: calls ERC721(0xdead).ownerOf(1) -> reverts -> returns false
        // Bug: calls ERC721(0xdead).ownerOf(1) -> reverts -> returns false (same!)
        // We need the token to exist. 

        // Better approach: deploy an actual ERC721 contract and mint a token to the pool
        // Let's use a minimal mint to set up the scene
        // Since we can't deploy another contract in this test, we'll use the fact that the factory
        // is address(this) and we can mint by calling internal functions? No, that's not allowed.

        // Alternative: use a pre-existing address with code
        // Let's create a simple ERC721 inline? No, only one contract C exists.

        // Given the constraints, the earlier approach that was rejected tried this:
        // Init with _baseToken=0x1111 and _nft=0x2222
        // Then call availableForFlashLoan(0x2222, 1)
        // But that required the NFT to actually hold the token.

        // Since we can only use the C contract and its interactions, let's think of another property.

        // The difference in baseToken vs nft affects the price function:
        // price() returns (virtualBaseTokenReserves * 10**exponent) / virtualNftReserves
        // where exponent = baseToken == address(0) ? 18 : (36 - ERC20(baseToken).decimals())
        // So if baseToken is different, the computation changes.

        // Let's try: initialize with baseToken=address(0) (ETH) and nft=0xdead
        // Reference: baseToken = address(0), so price uses exponent=18
        // Bug: baseToken = 0xdead (from _nft), so price calls ERC20(0xdead).decimals() which reverts
        // This gives a revert difference!

        // But the instruction says: P and M differ in that after availableForFlashLoan call, baseToken differs.
        // However we can also observe the price function.

        // Let's just use the exact scenario from the hint, making the token actually exist.
        // We'll use the C contract itself as a pseudo-ERC721 by predetermining its address?
        // No, C is not an ERC721 (though it has a receiver).

        // Given time, I'll output the most direct: after init, observe baseToken getter.

        // Initialize the pool
        c.initialize(
            0x1111111111111111111111111111111111111111, // _baseToken
            0x2222222222222222222222222222222222222222, // _nft
            1000,
            1000,
            0,
            100,
            0x0,
            false,
            false
        );

        // Now call availableForFlashLoan to trigger the state difference
        // This call itself doesn't change state, but after it completes,
        // baseToken differs between reference and bug
        try c.availableForFlashLoan(0x2222222222222222222222222222222222222222, 1) {} catch {}

        // The actual divergence: baseToken getter
        bool baseTokenMatchesExpected = c.baseToken() == 0x1111111111111111111111111111111111111111;

        // Reference: baseToken = 0x1111...1111 (correct)
        // Bug: baseToken = 0x2222...2222 (swapped)
        // So assertTrue should check that baseToken matches the intended _baseToken
        assertTrue(baseTokenMatchesExpected);
    }
}

