pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a simple ERC721 to use as nft
        ERC721Mock nftToken = new ERC721Mock();
        // Mint token 42 to this contract (so we can deposit it into the pool)
        nftToken.mint(address(this), 42);
        // Approve the pool to transfer the token
        nftToken.approve(address(c), 42);

        // Initialize the pool with _nft = address(nftToken) and _baseToken = address(0) (ETH)
        c.initialize(
            address(0),                // _baseToken
            address(nftToken),         // _nft
            100 ether,                  // _virtualBaseTokenReserves
            10 ether,                   // _virtualNftReserves
            0,                          // _changeFee
            0,                          // _feeRate
            bytes32(0),                 // _merkleRoot
            false,                      // _useStolenNftOracle
            false                       // _payRoyalties
        );

        // Deposit token 42 into the pool
        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = 42;
        c.deposit(tokenIds, 0);

        // Now call availableForFlashLoan on the nft address (nftToken) with token 42
        // In the reference, nft = address(nftToken), so it checks ownerOf(42) == address(c) which is true => returns true
        // In the bug, nft = address(0), so it calls ownerOf on address(0) (which will fail) => returns false
        bool result = c.availableForFlashLoan(address(nftToken), 42);

        // The reference returns true (token is owned by pool), bug returns false
        assertTrue(result, "availableForFlashLoan should return true for a deposited token");
    }
}

// Minimal ERC721 for testing
contract ERC721Mock {
    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;

    function mint(address to, uint256 tokenId) external {
        _owners[tokenId] = to;
        _balances[to]++;
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        address owner = _owners[tokenId];
        require(owner != address(0), "NOT_MINTED");
        return owner;
    }

    function approve(address spender, uint256 tokenId) external {
        // no-op for test
    }

    function transferFrom(address from, address to, uint256 tokenId) external {
        _owners[tokenId] = to;
        _balances[from]--;
        _balances[to]++;
    }
}

