    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a mock NFT to be used as _nft
        address nft = address(0x1234);
        // Deploy a mock base token
        address baseToken = address(0x5678);
        // Initialize the pool with _nft set to nft (non-zero)
        c.initialize(baseToken, nft, 1000 ether, 100 ether, 1, 100, bytes32(0), false, false);

        // Mint a token (tokenId = 1) to the pool directly by setting owner via internal _mint? 
        // We cannot call internal functions, but we can simulate by sending an NFT via safeTransferFrom
        // For simplicity, we use vm.prank to impersonate the nft contract to transfer token 1 to pool
        // But availableForFlashLoan checks ERC721(nft).ownerOf(tokenId), so we need that call to succeed
        // and return address(c). We'll use vm.mockCall to make ownerOf return address(c) when called with tokenId 1

        // Mock ownerOf on nft to return address(c) for token 1
        vm.mockCall(nft, abi.encodeWithSignature("ownerOf(uint256)", 1), abi.encode(address(c)));

        // Now call availableForFlashLoan with the correct nft address and tokenId 1
        bool result;
        try c.availableForFlashLoan(nft, 1) {
